--
-- Name: check_money(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.check_money() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare k text; payers int; payer text;
begin
  if jsonb_pence_sum(new.shares) <> new.amount_pence then
    raise exception 'shares (%) must sum to amount (%)', jsonb_pence_sum(new.shares), new.amount_pence;
  end if;
  if jsonb_pence_sum(new.paid) <> new.amount_pence then
    raise exception 'paid (%) must sum to amount (%)', jsonb_pence_sum(new.paid), new.amount_pence;
  end if;
  if exists (select 1 from jsonb_each_text(new.shares || new.paid) t(k, v) where v::bigint < 0)
     or exists (select 1 from jsonb_each_text(new.paid) t(k, v) where v::bigint < 0) then
    raise exception 'amounts must not be negative';
  end if;
  for k in select jsonb_object_keys(new.shares) union select jsonb_object_keys(new.paid) loop
    if not exists (select 1 from members m where m.household_id = new.household_id and m.user_id::text = k) then
      raise exception 'paid or shares name a non-member';
    end if;
  end loop;
  select count(*), min(t.k) into payers, payer from jsonb_each_text(new.paid) t(k, v) where v::bigint > 0;
  if new.split_mode = 'for_other' and (payers <> 1 or coalesce((new.shares ->> payer)::bigint, 0) <> 0) then
    raise exception 'paid-for-the-other: one person pays and owes nothing';
  end if;
  if new.split_mode = 'treat' and exists (
       select 1 from members m where m.household_id = new.household_id
        and coalesce((new.shares ->> m.user_id::text)::bigint, 0) <> coalesce((new.paid ->> m.user_id::text)::bigint, 0)) then
    raise exception 'treat: whoever pays covers it';
  end if;
  return new;
end $$;

--
-- Name: check_refund_limit(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.check_refund_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_amount bigint; v_back bigint; v_left bigint;
begin
  if new.kind <> 'money_back' or new.refund_of is null or new.deleted_at is not null then return new; end if;
  if coalesce(current_setting('smsm.restoring', true), '') = 'on' then return new; end if;
  -- Only a change that raises what has come back is checked.
  if tg_op = 'UPDATE' and old.kind = 'money_back' and old.deleted_at is null and old.refund_of is not distinct from new.refund_of
     and new.amount_pence <= old.amount_pence then
    return new;
  end if;
  -- One refund at a time per original (two phones at once can't both squeeze in).
  select amount_pence into v_amount from expenses where id = new.refund_of for update;
  if not found then return new; end if;
  select coalesce(sum(amount_pence), 0) into v_back from expenses
   where refund_of = new.refund_of and kind = 'money_back' and deleted_at is null and id <> new.id;
  v_left := greatest(v_amount - v_back, 0);
  if new.amount_pence > v_left then
    raise exception 'that''s more than the £%.% still to come back', v_left / 100, lpad((v_left % 100)::text, 2, '0')
      using errcode = '23514';
  end if;
  return new;
end $$;

--
-- Name: clear_category_guess(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.clear_category_guess() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  -- A guess is written together with its mark; any other change of category is a person's, and ends the guess.
  if new.category_id is distinct from old.category_id and new.category_guess is not distinct from old.category_guess then
    new.category_guess := false;
  end if;
  return new;
end $$;

