    (hid, 'Travel',        '✈️', 'lake',   9),
    (hid, 'Gifts',         '🎁', 'clay',   10),
    (hid, 'Health',        '💊', 'fern',   11),
    (hid, 'Other',         '📦', 'stone',  12);
