--
-- Name: next_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.next_notifications(p_limit integer) RETURNS TABLE(id uuid, recipient uuid, kind text, data jsonb, names jsonb, animal text, badge integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
begin
  delete from notification_outbox o where o.sent_at is null and o.created_at < now() - interval '2 days';
  delete from notification_outbox o where o.sent_at is not null and o.sent_at < now() - interval '7 days';
  update notification_outbox o set sent_at = now() where o.sent_at is null and not notification_enabled(o.recipient, o.kind);
  -- A balance reminder whose balance has come back within the person's amount since it was queued says nothing.
  update notification_outbox o set sent_at = now()
   where o.sent_at is null and o.kind = 'balance_reminder'
     and coalesce((select abs(b.net_pence) from member_net b where b.household_id = o.household_id and b.user_id = o.recipient), 0)
         <= coalesce((o.payload ->> 'threshold')::bigint, 0);
  return query
  with picked as (
    select o.id from notification_outbox o
     where o.sent_at is null and (o.claimed_at is null or o.claimed_at < now() - interval '2 minutes')
     order by o.created_at, o.id
     limit greatest(coalesce(p_limit, 0), 0)
     for update skip locked
  ), claimed as (
    update notification_outbox o set claimed_at = now() from picked where o.id = picked.id returning o.*
  )
  select c.id, c.recipient, c.kind, notification_data(c::notification_outbox),
         (select coalesce(jsonb_object_agg(m.user_id::text, m.display_name), '{}') from members m where m.household_id = c.household_id),
         (select m.animal from members m where m.household_id = c.household_id and m.user_id = c.actor),
         ((select count(*) from inbox_items i where i.household_id = c.household_id and i.status = 'open')
          + (select count(*) from change_requests q where q.household_id = c.household_id and q.status = 'pending' and q.requested_by <> c.recipient))::int
    from claimed c
   order by c.created_at, c.id;
end $$;

--
-- Name: note_push_result(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.note_push_result(p_endpoint text, p_ok boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_ok then
    update push_subscriptions set last_ok_at = now(), failing_since = null where endpoint = p_endpoint;
  else
    update push_subscriptions set failing_since = coalesce(failing_since, now()) where endpoint = p_endpoint;
    delete from push_subscriptions where endpoint = p_endpoint and failing_since < now() - interval '24 hours';
  end if;
end $$;

--
-- Name: notification_outbox; Type: TABLE; Schema: public; Owner: -
--
CREATE TABLE public.notification_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    household_id uuid NOT NULL,
    recipient uuid NOT NULL,
    actor uuid,
    kind text NOT NULL,
    ref_id uuid,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    sent_at timestamp with time zone,
    CONSTRAINT notification_outbox_kind_check CHECK ((kind = ANY (ARRAY['entry_added'::text, 'entry_changed'::text, 'entry_deleted'::text, 'entry_restored'::text, 'settle_added'::text, 'settle_changed'::text, 'settle_deleted'::text, 'comment'::text, 'approval_waiting'::text, 'approval_decided'::text, 'bill_posted'::text, 'bill_tomorrow'::text, 'recap_ready'::text, 'settle_day'::text, 'balance_reminder'::text])))
);

--
-- Name: notification_data(public.notification_outbox); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.notification_data(o public.notification_outbox) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d jsonb; v_balance jsonb; e expenses; s settlements; cr change_requests; r recurring; v_body text;
begin
  select coalesce(jsonb_object_agg(user_id::text, net_pence::bigint), '{}') into v_balance from member_net where household_id = o.household_id;
  d := jsonb_build_object('actor', o.actor, 'ref', o.ref_id, 'balance', v_balance);
  if o.kind in ('entry_added', 'entry_changed', 'entry_deleted', 'entry_restored', 'bill_posted') then
    select * into e from expenses where id = o.ref_id;
    d := d || jsonb_build_object('description', e.description, 'amount', e.amount_pence);
    -- A change: the amount (the words give the new one), only the category, or other details.
    if o.kind = 'entry_changed' and jsonb_typeof(o.payload -> 'fields') = 'array' then
      if o.payload -> 'fields' ? 'amount_pence' then
        d := d || jsonb_build_object('change', 'amount');
      elsif o.payload -> 'fields' = '["category_id"]'::jsonb then
        d := d || jsonb_build_object('change', 'category', 'category', (select c.name from categories c where c.id = e.category_id));
      else
        d := d || jsonb_build_object('change', 'details');
      end if;
    end if;
  elsif o.kind in ('settle_added', 'settle_changed', 'settle_deleted') then
    select * into s from settlements where id = o.ref_id;
    d := d || jsonb_build_object('amount', s.amount_pence, 'from', s.from_user);
  elsif o.kind = 'comment' then
    select * into e from expenses where id = o.ref_id;
    select body into v_body from comments where id = (o.payload ->> 'comment_id')::uuid;
    d := d || jsonb_build_object('description', e.description, 'comment', v_body, 'commentId', o.payload ->> 'comment_id');
  elsif o.kind in ('approval_waiting', 'approval_decided') then
    select * into cr from change_requests where id = o.ref_id;
    d := d || jsonb_build_object('request', cr.kind, 'approved', cr.status = 'approved');
  elsif o.kind = 'bill_tomorrow' then
    select * into r from recurring where id = o.ref_id;
    d := d || jsonb_build_object('description', r.description, 'amount', r.amount_pence, 'varies', r.amount_varies);
  elsif o.kind = 'recap_ready' then
    d := d || jsonb_build_object('month', o.payload ->> 'month');
  elsif o.kind = 'balance_reminder' then
    d := d || jsonb_build_object('threshold', (o.payload ->> 'threshold')::bigint);
  end if;
  return jsonb_strip_nulls(d);
end $$;

--
-- Name: notification_enabled(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.notification_enabled(p_user uuid, p_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when p_kind in ('approval_waiting', 'approval_decided') then true
    when p_kind in ('entry_added', 'entry_changed', 'entry_deleted', 'entry_restored') then coalesce((select entries from notification_prefs where user_id = p_user), true)
    when p_kind in ('settle_added', 'settle_changed', 'settle_deleted') then coalesce((select settle_ups from notification_prefs where user_id = p_user), true)
    when p_kind = 'comment' then coalesce((select comments from notification_prefs where user_id = p_user), true)
    when p_kind = 'bill_posted' then coalesce((select bills_today from notification_prefs where user_id = p_user), true)
    when p_kind = 'bill_tomorrow' then coalesce((select bills_tomorrow from notification_prefs where user_id = p_user), false)
    when p_kind in ('recap_ready', 'settle_day') then coalesce((select recap from notification_prefs where user_id = p_user), true)
    when p_kind = 'balance_reminder' then coalesce((select balance from notification_prefs where user_id = p_user), false)
    else false
  end
$$;

--
-- Name: notify_change_request(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.notify_change_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then return null; end if;
  if tg_op = 'INSERT' then
    if new.status = 'pending' then perform queue_notification(new.household_id, auth.uid(), 'approval_waiting', new.id); end if;
  elsif old.status = 'pending' and new.status in ('approved', 'declined') and new.requested_by <> auth.uid() then
    perform queue_notification(new.household_id, auth.uid(), 'approval_decided', new.id);
  end if;
  return null;
end $$;

--
-- Name: notify_comment(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.notify_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or new.deleted_at is not null then return null; end if;
  perform queue_notification(new.household_id, auth.uid(), 'comment', new.expense_id, jsonb_build_object('comment_id', new.id));
  return null;
end $$;

--
-- Name: notify_expense(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.notify_expense() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_kind text; v_payload jsonb := '{}'; v_fields jsonb;
begin
  if auth.uid() is null then return null; end if;
  if current_setting('smsm.following', true) = 'on' then return null; end if;
  if tg_op = 'INSERT' then
    if current_setting('smsm.posting', true) = 'on' or new.deleted_at is not null then return null; end if;
    v_kind := 'entry_added';
  elsif old.deleted_at is null and new.deleted_at is not null then
    v_kind := 'entry_deleted';
  elsif old.deleted_at is not null and new.deleted_at is null then
    v_kind := 'entry_restored';
  elsif new.deleted_at is not null then
    return null;
  elsif (to_jsonb(new) - 'updated_at' - 'updated_by') = (to_jsonb(old) - 'updated_at' - 'updated_by') then
    return null;
  else
    v_kind := 'entry_changed';
    select coalesce(jsonb_agg(n.key order by n.key), '[]') into v_fields
      from jsonb_each(to_jsonb(new) - 'updated_at' - 'updated_by' - 'category_guess') n
     where n.value is distinct from to_jsonb(old) -> n.key;
    v_payload := jsonb_build_object('fields', v_fields);
  end if;
  perform queue_notification(new.household_id, auth.uid(), v_kind, new.id, v_payload);
  return null;
end $$;

--
-- Name: notify_settlement(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.notify_settlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_kind text;
begin
  if auth.uid() is null then return null; end if;
  if tg_op = 'INSERT' then
    if new.deleted_at is not null then return null; end if;
    v_kind := 'settle_added';
  elsif old.deleted_at is null and new.deleted_at is not null then
    v_kind := 'settle_deleted';
  elsif old.deleted_at is not null and new.deleted_at is null then
    v_kind := 'settle_added';   -- restored: it counts again, as a settle-up
  elsif new.deleted_at is not null then
    return null;
  elsif (to_jsonb(new) - 'updated_at') = (to_jsonb(old) - 'updated_at') then
    return null;
  else
    v_kind := 'settle_changed';
  end if;
  perform queue_notification(new.household_id, auth.uid(), v_kind, new.id);
  return null;
end $$;

--
-- Name: post_due_recurring(uuid); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.post_due_recurring(p_household uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r recurring; d date; step interval; posted int := 0; hid uuid; home char(2); v_id uuid; v_late boolean;
        uk_today date := (now() at time zone 'Europe/London')::date;
begin
  if auth.uid() is not null and p_household is not null and p_household is distinct from my_household() then
    raise exception 'not your household';
  end if;
  if auth.uid() is null and current_setting('role', true) in ('anon', 'authenticated') then
    raise exception 'not signed in';
  end if;
  hid := coalesce(p_household, my_household());
  if hid is null then return 0; end if;
  perform set_config('smsm.posting', 'on', true);
  v_late := exists (select 1 from notification_daily_runs where day = uk_today)
            and (select count(*) from members x where x.household_id = hid) = 2;
  select home_country into home from households where id = hid;
  for r in select * from recurring where household_id = hid and active order by id for update loop
    step := case r.frequency when 'weekly' then make_interval(weeks => r.every)
                             when 'monthly' then make_interval(months => r.every)
                             else make_interval(years => r.every) end;
    loop
      d := (r.start_date + step * r.posted_count)::date;
      exit when d > uk_today or (r.end_date is not null and d > r.end_date);
      if r.amount_varies then
        insert into inbox_items(household_id, source, recurring_id, occurrence_date, payload)
        values (r.household_id, 'bill', r.id, d, jsonb_build_object('description', r.description,
                'estimate_pence', r.amount_pence, 'date', d, 'category_id', r.category_id))
        on conflict do nothing;
      else
        v_id := null;
        insert into expenses(household_id, description, amount_pence, date, category_id, chapter_id, paid, paid_via,
                             split_mode, split_params, shares, notes, country, source, recurring_id, occurrence_date)
        values (r.household_id, r.description, r.amount_pence, d, r.category_id, null, r.paid, r.paid_via,
                r.split_mode, r.split_params, r.shares, r.notes, coalesce(home, 'GB'), 'recurring', r.id, d)
        on conflict do nothing
        returning id into v_id;
        if v_late and v_id is not null and d = uk_today then
          insert into notification_outbox(household_id, recipient, kind, ref_id, payload)
          select hid, m.user_id, 'bill_posted', v_id, jsonb_build_object('recurring_id', r.id) from members m where m.household_id = hid;
        end if;
      end if;
      r.posted_count := r.posted_count + 1;
      posted := posted + 1;
    end loop;
    update recurring set posted_count = r.posted_count where id = r.id and posted_count is distinct from r.posted_count;
  end loop;
  perform set_config('smsm.posting', 'off', true);
  if v_late then perform kick_push(); end if;
  return posted;
end $$;

--
-- Name: post_due_recurring_all(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.post_due_recurring_all() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare h uuid; total int := 0;
begin
  for h in select id from households order by id loop
    begin
      total := total + post_due_recurring(h);
    exception when others then
      raise warning 'post_due_recurring failed for household %: %', h, sqlerrm;
    end;
  end loop;
  return total;
end $$;

--
-- Name: push_endpoint_ok(text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.push_endpoint_ok(p_endpoint text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select coalesce(length(p_endpoint) <= 2048
    and substring(p_endpoint from '^https://([^/:?#\s]+)/') ~ '^(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|([a-z0-9-]+\.)+push\.apple\.com|([a-z0-9-]+\.)+notify\.windows\.com)$',
    false)
$_$;

--
-- Name: push_public_key(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.push_public_key() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select vapid_public from push_config where id
$$;

--
-- Name: queue_daily_notifications(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.queue_daily_notifications(p_now timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_local timestamp := p_now at time zone 'Europe/London'; d date := (p_now at time zone 'Europe/London')::date;
        n int := 0; c int;
begin
  if extract(hour from v_local) <> 8 then return 0; end if;
  insert into notification_daily_runs(day) values (d) on conflict do nothing;
  if not found then return 0; end if;
  delete from notification_daily_runs where day < d - 400;

  -- A shared regular payment posted today: both.
  insert into notification_outbox(household_id, recipient, kind, ref_id, payload)
  select e.household_id, m.user_id, 'bill_posted', e.id, jsonb_build_object('recurring_id', e.recurring_id)
    from expenses e join members m on m.household_id = e.household_id
   where e.recurring_id is not null and e.source = 'recurring' and e.occurrence_date = d and e.deleted_at is null
     and (select count(*) from members x where x.household_id = e.household_id) = 2
     and not exists (select 1 from notification_outbox a where a.kind = 'bill_posted' and a.ref_id = e.id);
  get diagnostics c = row_count; n := n + c;

  -- A shared bill posts tomorrow (its next occurrence): both (most have the switch off).
  insert into notification_outbox(household_id, recipient, kind, ref_id)
  select r.household_id, m.user_id, 'bill_tomorrow', r.id
    from recurring r join members m on m.household_id = r.household_id
   where r.active and (r.end_date is null or r.end_date >= d + 1)
     and exists (select 1 from generate_series(r.posted_count, r.posted_count + 3) k
                  where (r.start_date + recurring_step(r.frequency, r.every) * k)::date = d + 1)
     and (select count(*) from members x where x.household_id = r.household_id) = 2;
  get diagnostics c = row_count; n := n + c;

  -- The 1st: last month's recap, where last month has something in it.
  if extract(day from d) = 1 then
    insert into notification_outbox(household_id, recipient, kind, payload)
    select h.id, m.user_id, 'recap_ready', jsonb_build_object('month', to_char(d - 1, 'YYYY-MM'))
      from households h join members m on m.household_id = h.id
     where (select count(*) from members x where x.household_id = h.id) = 2
       and exists (select 1 from expenses e where e.household_id = h.id and e.deleted_at is null
                     and e.date between date_trunc('month', d - 1)::date and d - 1);
    get diagnostics c = row_count; n := n + c;
  end if;

  -- Settle day, unless the two are square.
  insert into notification_outbox(household_id, recipient, kind)
  select h.id, m.user_id, 'settle_day'
    from households h join members m on m.household_id = h.id
   where h.settle_day = extract(day from d)
     and (select count(*) from members x where x.household_id = h.id) = 2
     and exists (select 1 from member_net b where b.household_id = h.id and b.net_pence <> 0);
  get diagnostics c = row_count; n := n + c;

  -- The balance above a person's chosen amount (the same way round) on each of the last 30 days: that person, at
  -- most once every 30 days.
  with due as (
    select m.household_id, m.user_id, p.balance_threshold_pence as threshold
      from members m join notification_prefs p on p.user_id = m.user_id and p.balance
     where (select count(*) from members x where x.household_id = m.household_id) = 2
       and not exists (select 1 from notification_reminders r where r.user_id = m.user_id and r.last_sent > d - 30)
       and (select bool_and(q.net > p.balance_threshold_pence) or bool_and(q.net < -p.balance_threshold_pence)
              from (select member_net_on(m.household_id, m.user_id, x::date) as net
                      from generate_series(d - 29, d, interval '1 day') x) q)
  ), queued as (
    insert into notification_outbox(household_id, recipient, kind, payload)
    select household_id, user_id, 'balance_reminder', jsonb_build_object('threshold', threshold) from due
    returning recipient
  )
  insert into notification_reminders(user_id, last_sent) select recipient, d from queued
  on conflict (user_id) do update set last_sent = excluded.last_sent;
  get diagnostics c = row_count; n := n + c;

  if n > 0 then perform kick_push(); end if;
  return n;
end $$;

--
-- Name: queue_notification(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.queue_notification(p_household uuid, p_actor uuid, p_kind text, p_ref uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_recipient uuid; v_any boolean := false;
begin
  if p_actor is null or p_household is null then return; end if;
  if coalesce(current_setting('smsm.restoring', true), '') = 'on' then return; end if;
  for v_recipient in select user_id from members where household_id = p_household and user_id <> p_actor loop
    insert into notification_outbox(household_id, recipient, actor, kind, ref_id, payload)
    values (p_household, v_recipient, p_actor, p_kind, p_ref, coalesce(p_payload, '{}'));
    v_any := true;
  end loop;
  if v_any and current_setting('smsm.push_kicked', true) is distinct from 'on' then
    perform set_config('smsm.push_kicked', 'on', true);
    perform kick_push();
  end if;
end $$;

--
-- Name: recurring_guard(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.recurring_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare uk_today date := (now() at time zone 'Europe/London')::date; nxt date; n int := 0;
begin
  if tg_op = 'INSERT' then
    if current_user = 'authenticated' then new.posted_count := 0; end if;
    return new;
  end if;
  if current_user = 'authenticated' and new.posted_count is distinct from old.posted_count then
    raise exception 'posted_count is kept by the server' using errcode = '42501';
  end if;
  if old.posted_count > 0 and (new.frequency, new.every, new.start_date) is distinct from (old.frequency, old.every, old.start_date) then
    nxt := (old.start_date + recurring_step(old.frequency, old.every) * old.posted_count)::date;
    new.start_date := greatest(new.start_date, nxt);
    new.posted_count := 0;
  end if;
  if not old.active and new.active then
    loop
      exit when (new.start_date + recurring_step(new.frequency, new.every) * new.posted_count)::date >= uk_today or n >= 10000;
      new.posted_count := new.posted_count + 1;
      n := n + 1;
    end loop;
  end if;
  return new;
end $$;

--
-- Name: recurring_step(text, integer); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.recurring_step(p_frequency text, p_every integer) RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case p_frequency when 'weekly' then make_interval(weeks => p_every)
                          when 'monthly' then make_interval(months => p_every)
                          else make_interval(years => p_every) end
$$;

--
-- Name: remove_push_subscription(text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.remove_push_subscription(p_endpoint text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  delete from push_subscriptions where endpoint = p_endpoint and user_id = auth.uid();
end $$;

--
-- Name: request_change(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.request_change(p_kind text, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rid uuid; hid uuid := my_household();
begin
  if hid is null then raise exception 'not in a household'; end if;
  if (select count(*) from members where household_id = hid) < 2 then raise exception 'your partner has not joined yet'; end if;
  insert into change_requests(household_id, requested_by, kind, payload) values (hid, auth.uid(), p_kind, p_payload)
  returning id into rid;
  insert into activity(household_id, actor, entity, entity_id, action, summary)
  values (hid, auth.uid(), 'change_request', rid, 'requested', jsonb_build_object('kind', p_kind, 'payload', p_payload));
  return rid;
end $$;

--
-- Name: restore_backup(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.restore_backup(p_people jsonb, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  hid uuid := my_household();
  r jsonb; old uuid; tgt uuid; n_rows int := 0;
  added jsonb := '{}'::jsonb; skipped jsonb := '{}'::jsonb;
  e expenses; s settlements; c categories; ch chapters; rc recurring; cm comments;
  member_ids uuid[]; mapped uuid[];
  t text;
  cur text := '';
begin
  if hid is null then raise exception 'not in a household' using errcode = '42501'; end if;
  select array_agg(user_id order by user_id) into member_ids from members where household_id = hid;
  if coalesce(array_length(member_ids, 1), 0) <> 2 then
    raise exception 'both of you need to have joined before restoring' using errcode = '22023';
  end if;
  if p_people is null or jsonb_typeof(p_people) <> 'object' then raise exception 'no people map' using errcode = '22023'; end if;
  select array_agg(distinct v::uuid order by v::uuid) into mapped from jsonb_each_text(p_people) t(k, v);
  if (select count(*) from jsonb_object_keys(p_people)) <> 2 or mapped is distinct from member_ids then
    raise exception 'map the backup''s two people to the two of you' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'object' then raise exception 'no rows' using errcode = '22023'; end if;
  foreach t in array array['categories','chapters','recurring','expenses','settlements','comments','category_memory','import_rules'] loop
    if p_rows ? t and jsonb_typeof(p_rows -> t) <> 'array' then raise exception '% must be a list', t using errcode = '22023'; end if;
    n_rows := n_rows + coalesce(jsonb_array_length(p_rows -> t), 0);
    added := added || jsonb_build_object(t, 0);
    skipped := skipped || jsonb_build_object(t, 0);
  end loop;
  if n_rows > 500 then raise exception 'at most 500 rows a call' using errcode = '22023'; end if;
  perform set_config('smsm.restoring', 'on', true);

  begin
  -- Categories: by id, then by name; otherwise added.
  cur := 'categories';
  for r in select * from jsonb_array_elements(coalesce(p_rows -> 'categories', '[]')) loop
    old := (r ->> 'id')::uuid;
    if restore_target(hid, old, 'categories') is null then
      select id into tgt from categories where household_id = hid and lower(btrim(name)) = lower(btrim(r ->> 'name')) limit 1;
      if tgt is not null then
        insert into restore_ids values (hid, old, tgt) on conflict do nothing;
        skipped := jsonb_set(skipped, '{categories}', to_jsonb((skipped ->> 'categories')::int + 1));
        continue;
      end if;
      c := jsonb_populate_record(null::categories, r);
      c.id := restore_new_id(hid, old, 'categories');
      c.household_id := hid;
      c.default_ratio := restore_remap_keys(c.default_ratio, p_people);
      c.emoji := coalesce(c.emoji, '•'); c.colour := coalesce(c.colour, 'stone'); c.archived := coalesce(c.archived, false);
      c.sort := coalesce(c.sort, 0); c.updated_at := coalesce(c.updated_at, now());
      insert into categories select c.*;
      added := jsonb_set(added, '{categories}', to_jsonb((added ->> 'categories')::int + 1));
    else
      skipped := jsonb_set(skipped, '{categories}', to_jsonb((skipped ->> 'categories')::int + 1));
    end if;
  end loop;

  cur := 'chapters';
  for r in select * from jsonb_array_elements(coalesce(p_rows -> 'chapters', '[]')) loop
    old := (r ->> 'id')::uuid;
    if restore_target(hid, old, 'chapters') is not null then
      skipped := jsonb_set(skipped, '{chapters}', to_jsonb((skipped ->> 'chapters')::int + 1)); continue;
    end if;
    ch := jsonb_populate_record(null::chapters, r);
    ch.id := restore_new_id(hid, old, 'chapters');
    ch.household_id := hid;
    ch.emoji := coalesce(ch.emoji, '🌿'); ch.kind := coalesce(ch.kind, 'project'); ch.closed := coalesce(ch.closed, false);
    ch.created_at := coalesce(ch.created_at, now()); ch.updated_at := coalesce(ch.updated_at, now());
    ch.created_by := restore_person(ch.created_by, p_people, member_ids);
    insert into chapters select ch.*;
    added := jsonb_set(added, '{chapters}', to_jsonb((added ->> 'chapters')::int + 1));
  end loop;

  cur := 'recurring';
  for r in select * from jsonb_array_elements(coalesce(p_rows -> 'recurring', '[]')) loop
    old := (r ->> 'id')::uuid;
    if restore_target(hid, old, 'recurring') is not null then
      skipped := jsonb_set(skipped, '{recurring}', to_jsonb((skipped ->> 'recurring')::int + 1)); continue;
    end if;
    rc := jsonb_populate_record(null::recurring, r);
    rc.id := restore_new_id(hid, old, 'recurring');
    rc.household_id := hid;
    rc.active := false;  -- paused: nothing posts on its own after a restore
    rc.category_id := restore_ref(hid, rc.category_id, 'categories');
    rc.paid := restore_remap_keys(rc.paid, p_people);
    rc.shares := restore_remap_keys(rc.shares, p_people);
    rc.split_params := restore_remap_keys(rc.split_params, p_people);
    rc.amount_varies := coalesce(rc.amount_varies, false); rc.paid_via := coalesce(rc.paid_via, 'person');
    rc.split_mode := coalesce(rc.split_mode, 'ratio'); rc.is_subscription := coalesce(rc.is_subscription, false);
    rc.every := coalesce(rc.every, 1); rc.posted_count := coalesce(rc.posted_count, 0);
    rc.created_at := coalesce(rc.created_at, now()); rc.updated_at := coalesce(rc.updated_at, now());
    rc.created_by := restore_person(rc.created_by, p_people, member_ids);
    insert into recurring select rc.*;
    added := jsonb_set(added, '{recurring}', to_jsonb((added ->> 'recurring')::int + 1));
  end loop;

  -- Entries before money back, so a refund finds the entry it refunds within the same call.
  cur := 'expenses';
  for r in select x from jsonb_array_elements(coalesce(p_rows -> 'expenses', '[]')) x
           order by (x ->> 'kind') = 'money_back', x ->> 'created_at' loop
    old := (r ->> 'id')::uuid;
    if restore_target(hid, old, 'expenses') is not null then
      skipped := jsonb_set(skipped, '{expenses}', to_jsonb((skipped ->> 'expenses')::int + 1)); continue;
    end if;
    e := jsonb_populate_record(null::expenses, r);
    e.id := restore_new_id(hid, old, 'expenses');
    e.household_id := hid;
    e.category_id := restore_ref(hid, e.category_id, 'categories');
    e.chapter_id := restore_ref(hid, e.chapter_id, 'chapters');
    e.recurring_id := restore_ref(hid, e.recurring_id, 'recurring');
    e.refund_of := restore_ref(hid, e.refund_of, 'expenses');
    e.account_id := null;
    -- Photos aren't in a backup: a path from another household points at nothing here.
    if e.receipt_path is not null and split_part(e.receipt_path, '/', 1) <> hid::text then e.receipt_path := null; end if;
    e.paid := restore_remap_keys(e.paid, p_people);
    e.shares := restore_remap_keys(e.shares, p_people);
    e.split_params := restore_remap_keys(e.split_params, p_people);
    if e.recurring_id is null then e.occurrence_date := null; end if;
    e.kind := coalesce(e.kind, 'expense'); e.paid_via := coalesce(e.paid_via, 'person'); e.split_mode := coalesce(e.split_mode, 'ratio');
    e.country := coalesce(e.country, 'GB'); e.tags := coalesce(e.tags, '{}'); e.source := coalesce(e.source, 'manual');
    e.category_guess := coalesce(e.category_guess, false); e.created_at := coalesce(e.created_at, now()); e.updated_at := coalesce(e.updated_at, now());
    e.created_by := restore_person(e.created_by, p_people, member_ids);
    e.updated_by := restore_person(e.updated_by, p_people, member_ids);
    insert into expenses select e.* on conflict do nothing;
    if found then
      added := jsonb_set(added, '{expenses}', to_jsonb((added ->> 'expenses')::int + 1));
    else
      skipped := jsonb_set(skipped, '{expenses}', to_jsonb((skipped ->> 'expenses')::int + 1));
    end if;
  end loop;

  cur := 'settlements';
  for r in select * from jsonb_array_elements(coalesce(p_rows -> 'settlements', '[]')) loop
    old := (r ->> 'id')::uuid;
    if restore_target(hid, old, 'settlements') is not null then
      skipped := jsonb_set(skipped, '{settlements}', to_jsonb((skipped ->> 'settlements')::int + 1)); continue;
    end if;
    s := jsonb_populate_record(null::settlements, r);
    s.id := restore_new_id(hid, old, 'settlements');
    s.household_id := hid;
    s.from_user := coalesce((p_people ->> s.from_user::text)::uuid, s.from_user);
    s.to_user := coalesce((p_people ->> s.to_user::text)::uuid, s.to_user);
    if not (s.from_user = any (member_ids) and s.to_user = any (member_ids)) then
      raise exception 'a settle-up names someone who isn''t one of you' using errcode = '22023';
    end if;
    s.method := coalesce(s.method, 'other'); s.created_at := coalesce(s.created_at, now()); s.updated_at := coalesce(s.updated_at, now());
    s.created_by := restore_person(s.created_by, p_people, member_ids);
    insert into settlements select s.*;
    added := jsonb_set(added, '{settlements}', to_jsonb((added ->> 'settlements')::int + 1));
  end loop;

  cur := 'comments';
  for r in select * from jsonb_array_elements(coalesce(p_rows -> 'comments', '[]')) loop
    old := (r ->> 'id')::uuid;
    cm := jsonb_populate_record(null::comments, r);
    cm.expense_id := restore_ref(hid, cm.expense_id, 'expenses');
    if restore_target(hid, old, 'comments') is not null or cm.expense_id is null then
      skipped := jsonb_set(skipped, '{comments}', to_jsonb((skipped ->> 'comments')::int + 1)); continue;
    end if;
    cm.id := restore_new_id(hid, old, 'comments');
    cm.household_id := hid;
    cm.author := coalesce((p_people ->> cm.author::text)::uuid, cm.author);
    if not cm.author = any (member_ids) then
      raise exception 'a comment names someone who isn''t one of you' using errcode = '22023';
    end if;
    cm.created_at := coalesce(cm.created_at, now());
    insert into comments select cm.*;
    added := jsonb_set(added, '{comments}', to_jsonb((added ->> 'comments')::int + 1));
  end loop;

  cur := 'category_memory';
  for r in select * from jsonb_array_elements(coalesce(p_rows -> 'category_memory', '[]')) loop
    perform restore_check_split(r ->> 'split_mode', restore_remap_keys(r -> 'split_params', p_people), member_ids);
    insert into category_memory(household_id, key, category_id, split_mode, split_params, uses, source, updated_at)
    values (hid, r ->> 'key', restore_ref(hid, (r ->> 'category_id')::uuid, 'categories'), r ->> 'split_mode',
            restore_remap_keys(r -> 'split_params', p_people), coalesce((r ->> 'uses')::int, 1),
            coalesce(r ->> 'source', 'user'), coalesce((r ->> 'updated_at')::timestamptz, now()))
    on conflict do nothing;
    if found then added := jsonb_set(added, '{category_memory}', to_jsonb((added ->> 'category_memory')::int + 1));
    else skipped := jsonb_set(skipped, '{category_memory}', to_jsonb((skipped ->> 'category_memory')::int + 1)); end if;
  end loop;

  cur := 'import_rules';
  for r in select * from jsonb_array_elements(coalesce(p_rows -> 'import_rules', '[]')) loop
    -- A skip rule is one person's, kept on their phone: never restored into the shared record.
    if coalesce(r ->> 'decision', '') <> 'keep' then
      skipped := jsonb_set(skipped, '{import_rules}', to_jsonb((skipped ->> 'import_rules')::int + 1)); continue;
    end if;
    perform restore_check_split(r ->> 'split_mode', restore_remap_keys(r -> 'split_params', p_people), member_ids);
    insert into import_rules(household_id, match_text, decision, category_id, split_mode, split_params)
    values (hid, r ->> 'match_text', r ->> 'decision', restore_ref(hid, (r ->> 'category_id')::uuid, 'categories'),
            r ->> 'split_mode', restore_remap_keys(r -> 'split_params', p_people))
    on conflict do nothing;
    if found then added := jsonb_set(added, '{import_rules}', to_jsonb((added ->> 'import_rules')::int + 1));
    else skipped := jsonb_set(skipped, '{import_rules}', to_jsonb((skipped ->> 'import_rules')::int + 1)); end if;
  end loop;
  exception when others then
    -- Which part of the backup was refused, for the app to say in plain words; the whole call is undone.
    raise exception 'restore %: %', cur, sqlerrm using errcode = sqlstate;
  end;

  return jsonb_build_object('added', added, 'skipped', skipped);
end $$;

--
-- Name: restore_check_split(text, jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.restore_check_split(p_mode text, p_params jsonb, p_members uuid[]) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
begin
  if p_mode is not null and p_mode not in ('ratio', 'exact', 'for_other', 'treat') then
    raise exception 'unknown split %', p_mode using errcode = '22023';
  end if;
  if p_params is null or jsonb_typeof(p_params) = 'null' then return; end if;
  if jsonb_typeof(p_params) <> 'object' then raise exception 'a split must name its people' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_object_keys(p_params) k
              where case when k ~ '^[0-9a-fA-F-]{36}$' then not (k::uuid = any (p_members)) else true end) then
    raise exception 'a split names someone who isn''t one of you' using errcode = '22023';
  end if;
end $_$;

--
-- Name: restore_new_id(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.restore_new_id(p_hid uuid, p_old uuid, p_table text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare taken boolean; fresh uuid;
begin
  if p_old is null then return gen_random_uuid(); end if;
  execute format('select exists (select 1 from %I where id = $1)', p_table) into taken using p_old;
  if not taken then return p_old; end if;
  fresh := gen_random_uuid();
  insert into restore_ids values (p_hid, p_old, fresh)
  on conflict (household_id, old_id) do update set new_id = excluded.new_id;
  return fresh;
end $_$;

--
-- Name: restore_person(uuid, jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.restore_person(p_id uuid, p_people jsonb, p_members uuid[]) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when m = any (p_members) then m else null end
    from (select coalesce((p_people ->> p_id::text)::uuid, p_id) as m) x
$$;

--
-- Name: restore_ref(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.restore_ref(p_hid uuid, p_old uuid, p_table text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select restore_target(p_hid, p_old, p_table)
$$;

--
-- Name: restore_remap_keys(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.restore_remap_keys(j jsonb, p_people jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when j is null or jsonb_typeof(j) <> 'object' then j
    else coalesce((select jsonb_object_agg(coalesce(p_people ->> k, k), v) from jsonb_each(j) t(k, v)), '{}'::jsonb) end
$$;

--
-- Name: restore_target(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.restore_target(p_hid uuid, p_old uuid, p_table text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare found_id uuid;
begin
  if p_old is null then return null; end if;
  execute format('select id from %I where id = $1 and household_id = $2', p_table) into found_id using p_old, p_hid;
  if found_id is not null then return found_id; end if;
  select m.new_id into found_id from restore_ids m where m.household_id = p_hid and m.old_id = p_old;
  if found_id is not null then
    execute format('select id from %I where id = $1 and household_id = $2', p_table) into found_id using found_id, p_hid;
  end if;
  return found_id;
end $_$;

--
-- Name: save_push_subscription(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare uid uuid := auth.uid(); old push_subscriptions;
begin
  if uid is null then raise exception 'not signed in'; end if;
  if not push_endpoint_ok(p_endpoint) then raise exception 'that is not a push address'; end if;
  if coalesce(length(p_p256dh), 0) not between 1 and 200 or coalesce(length(p_auth), 0) not between 1 and 200 then
    raise exception 'the subscription''s keys are missing';
  end if;
  select * into old from push_subscriptions where endpoint = p_endpoint for update;
  if old.endpoint is null then
    insert into push_subscriptions(endpoint, user_id, p256dh, auth) values (p_endpoint, uid, p_p256dh, p_auth)
    on conflict (endpoint) do nothing;
  elsif old.user_id = uid then
    update push_subscriptions set p256dh = p_p256dh, auth = p_auth where endpoint = p_endpoint;
  else
    if (select household_id from members where user_id = old.user_id) is distinct from my_household() or my_household() is null then
      raise exception 'that push address belongs to someone else';
    end if;
    if old.p256dh <> p_p256dh or old.auth <> p_auth then
      raise exception 'that push address belongs to someone else';
    end if;
    update push_subscriptions set user_id = uid, created_at = now(), failing_since = null where endpoint = p_endpoint;
  end if;
end $$;

--
-- Name: save_recap_prose(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.save_recap_prose(p_period text, p_stats jsonb, p_prose text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare hid uuid := my_household(); kept text;
  this_month text := to_char((now() at time zone 'Europe/London')::date, 'YYYY-MM');
begin
  if hid is null then raise exception 'not in a household'; end if;
  if p_period is null or p_period !~ '^\d{4}-(0[1-9]|1[0-2])$' then raise exception 'not a month'; end if;
  if p_period >= this_month then raise exception 'only a finished month has its wording kept'; end if;
  if p_prose is null or btrim(p_prose) = '' then raise exception 'no wording'; end if;
  if p_stats is null then raise exception 'no figures'; end if;
  -- Two short sentences and a month's figures: nothing bigger is kept.
  if octet_length(p_prose) > 2000 then raise exception 'wording too long'; end if;
  if pg_column_size(p_stats) > 16384 then raise exception 'figures too large'; end if;
  insert into recaps(household_id, period, stats, prose) values (hid, p_period, p_stats, p_prose)
  on conflict (household_id, period) do nothing;  -- the primary key: once per household per month
  select prose into kept from recaps where household_id = hid and period = p_period;
  return kept;
end $_$;

--
-- Name: set_identity(text, text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.set_identity(p_name text, p_animal text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if exists (select 1 from members where user_id = auth.uid() and locked_at is not null) then
    raise exception 'already set; request a change instead';
  end if;
  if exists (select 1 from members where household_id = my_household() and animal = p_animal and user_id <> auth.uid()) then
    raise exception 'your partner already picked the %', p_animal;
  end if;
  perform set_config('smsm.applying_change', 'on', true);
  update members set display_name = trim(p_name), animal = p_animal, locked_at = now() where user_id = auth.uid();
  perform set_config('smsm.applying_change', 'off', true);
end $$;

--
-- Name: set_monzo_me(text); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.set_monzo_me(p_username text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
begin
  if p_username is not null and p_username !~ '^[A-Za-z0-9_-]{1,40}$' then raise exception 'that does not look like a monzo.me name'; end if;
  update members set monzo_me = p_username where user_id = auth.uid();
end $_$;

--
-- Name: notification_prefs; Type: TABLE; Schema: public; Owner: -
--
CREATE TABLE public.notification_prefs (
    user_id uuid NOT NULL,
    entries boolean DEFAULT true NOT NULL,
    settle_ups boolean DEFAULT true NOT NULL,
    comments boolean DEFAULT true NOT NULL,
    bills_today boolean DEFAULT true NOT NULL,
    bills_tomorrow boolean DEFAULT false NOT NULL,
    recap boolean DEFAULT true NOT NULL,
    balance boolean DEFAULT false NOT NULL,
    balance_threshold_pence bigint DEFAULT 10000 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notification_prefs_balance_threshold_pence_check CHECK (((balance_threshold_pence > 0) AND (balance_threshold_pence <= 100000000)))
);

--
-- Name: set_notification_prefs(jsonb); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.set_notification_prefs(p jsonb) RETURNS public.notification_prefs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare uid uuid := auth.uid(); k text; v numeric; r notification_prefs;
begin
  if uid is null then raise exception 'not signed in'; end if;
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'preferences must be an object'; end if;
  for k in select jsonb_object_keys(p) loop
    if k in ('entries', 'settle_ups', 'comments', 'bills_today', 'bills_tomorrow', 'recap', 'balance') then
      if jsonb_typeof(p -> k) <> 'boolean' then raise exception 'a switch is on or off'; end if;
    elsif k = 'balance_threshold_pence' then
      if jsonb_typeof(p -> k) <> 'number' then raise exception 'the amount is a whole number of pence above zero'; end if;
      v := (p ->> k)::numeric;
      if v <> trunc(v) or v <= 0 or v > 100000000 then raise exception 'the amount is a whole number of pence above zero'; end if;
    else
      raise exception 'no such notification setting: %', k;
    end if;
  end loop;
  insert into notification_prefs(user_id) values (uid) on conflict (user_id) do nothing;
  update notification_prefs set
    entries = coalesce((p ->> 'entries')::boolean, entries),
    settle_ups = coalesce((p ->> 'settle_ups')::boolean, settle_ups),
    comments = coalesce((p ->> 'comments')::boolean, comments),
    bills_today = coalesce((p ->> 'bills_today')::boolean, bills_today),
    bills_tomorrow = coalesce((p ->> 'bills_tomorrow')::boolean, bills_tomorrow),
    recap = coalesce((p ->> 'recap')::boolean, recap),
    balance = coalesce((p ->> 'balance')::boolean, balance),
    balance_threshold_pence = coalesce((p ->> 'balance_threshold_pence')::bigint, balance_threshold_pence),
    updated_at = now()
  where user_id = uid
  returning * into r;
  return r;
end $$;

--
-- Name: set_settle_day(integer); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.set_settle_day(p_day integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare hid uuid := my_household(); was smallint;
begin
  if hid is null then raise exception 'not in a household'; end if;
  if p_day is not null and (p_day < 1 or p_day > 28) then raise exception 'pick a day from 1 to 28'; end if;
  select settle_day into was from households where id = hid;
  if was is not distinct from p_day then return; end if;
  perform set_config('smsm.setting_settle_day', 'on', true);
  update households set settle_day = p_day where id = hid;
  perform set_config('smsm.setting_settle_day', 'off', true);
  insert into activity(household_id, actor, entity, entity_id, action, summary)
  values (hid, auth.uid(), 'household', hid, 'edited', jsonb_build_object('settle_day', jsonb_build_object('before', was, 'after', p_day)));
end $$;

--
-- Name: stamp_author(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.stamp_author() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare restoring boolean := coalesce(current_setting('smsm.restoring', true), '') = 'on';
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null then
      if not (restoring and new.created_by is not null) then new.created_by := auth.uid(); end if;
      -- (Nested: a row of another table has no updated_by to read.)
      if tg_table_name = 'expenses' then
        if not (restoring and new.updated_by is not null) then new.updated_by := auth.uid(); end if;
      end if;
    end if;
  else
    -- Nobody changes who made a row, whoever asks.
    new.created_by := old.created_by;
    if tg_table_name = 'expenses' and auth.uid() is not null then new.updated_by := auth.uid(); end if;
  end if;
  return new;
end $$;

--
-- Name: stamp_update(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.stamp_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at := now();
  if tg_table_name = 'expenses' then new.updated_by := coalesce(auth.uid(), new.updated_by); end if;
  return new;
end $$;

--
-- Name: storage_used(); Type: FUNCTION; Schema: public; Owner: -
--
CREATE FUNCTION public.storage_used() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare hid uuid := my_household(); photos bigint := 0;
begin
  if hid is null then raise exception 'not in a household' using errcode = '42501'; end if;
  if to_regclass('storage.objects') is not null then
    execute $q$select coalesce(sum((metadata ->> 'size')::bigint), 0) from storage.objects
               where bucket_id = 'receipts' and name like $1$q$ into photos using hid::text || '/%';
  end if;
  return jsonb_build_object('database_bytes', pg_database_size(current_database()), 'photo_bytes', photos);
end $_$;

